use crate::{ast::*,lexer::{Token,TokenKind},source::{CompileError,Span}};

pub struct Parser { toks:Vec<Token>, pos:usize }
impl Parser {
 pub fn new(toks:Vec<Token>)->Self{Self{toks,pos:0}}
 fn cur(&self)->&Token{&self.toks[self.pos]}
 fn at(&self,k:&TokenKind)->bool{std::mem::discriminant(&self.cur().kind)==std::mem::discriminant(k)}
 fn bump(&mut self)->Token{let t=self.cur().clone();self.pos+=1;t}
 fn eat(&mut self,k:&TokenKind)->bool{if self.at(k){self.bump();true}else{false}}
 fn need(&mut self,k:&TokenKind,msg:&str)->Result<Token,CompileError>{if self.at(k){Ok(self.bump())}else{Err(CompileError::new(self.cur().span,msg))}}
 fn ident(&mut self,msg:&str)->Result<(String,Span),CompileError>{match self.bump().kind{TokenKind::Ident(s)=>Ok((s,self.toks[self.pos-1].span)),_=>Err(CompileError::new(self.toks[self.pos-1].span,msg))}}
 fn nl(&mut self){while self.at(&TokenKind::Newline){self.bump();}}
 pub fn parse(mut self)->Result<Program,CompileError>{self.nl();let mut items=Vec::new();while !self.at(&TokenKind::Eof){if self.at(&TokenKind::Use){let t=self.bump();let s=match self.bump().kind{TokenKind::Str(s)=>s,_=>return Err(CompileError::new(self.cur().span,"USE expects a quoted .plain path"))};items.push(Item::Use(s,t.span));}else if self.at(&TokenKind::Extern){items.push(Item::Extern(self.extern_function()?));}else if self.at(&TokenKind::To){items.push(Item::Function(self.function()?));}else if self.at(&TokenKind::Class){items.push(Item::Class(self.class()?));}else{items.push(Item::Stmt(self.stmt()?));}self.nl();}Ok(Program{items})}
 fn type_name(&mut self)->Result<Type,CompileError>{match self.bump().kind{TokenKind::Ident(s)=>match s.to_ascii_lowercase().as_str(){"int"=>Ok(Type::Int),"float"=>Ok(Type::Float),"bool"=>Ok(Type::Bool),"string"=>Ok(Type::String),"dict"=>Ok(Type::Dict),"any"=>Ok(Type::Any),x=>Err(CompileError::new(self.toks[self.pos-1].span,format!("unknown type `{}`",x)))},TokenKind::LBracket=>{let t=self.type_name()?;self.need(&TokenKind::RBracket,"expected ] in list type")?;Ok(Type::List(Box::new(t)))},_=>Err(CompileError::new(self.toks[self.pos-1].span,"expected a type"))}}
 fn function(&mut self)->Result<Function,CompileError>{let start=self.need(&TokenKind::To,"expected TO")?.span;let nt=self.bump();let(name,_)=match nt.kind{TokenKind::Ident(s)=>(s,nt.span),TokenKind::New=>("NEW".to_string(),nt.span),_=>(return Err(CompileError::new(nt.span,"expected function name")))};let mut params=Vec::new();if self.eat(&TokenKind::LParen){if !self.at(&TokenKind::RParen){loop{let(p,_)=self.ident("expected parameter name")?;self.need(&TokenKind::As,"function parameters require AS type")?;let t=self.type_name()?;params.push((p,t));if !self.eat(&TokenKind::Comma){break}}}self.need(&TokenKind::RParen,"expected ) after parameters")?;}else if !self.at(&TokenKind::Gives)&&!self.at(&TokenKind::Newline){loop{let(p,_)=self.ident("expected parameter name")?;self.need(&TokenKind::As,"function parameters require AS type")?;let t=self.type_name()?;params.push((p,t));if !self.eat(&TokenKind::Comma){break}}}let ret=if self.eat(&TokenKind::Gives){self.type_name()?}else{Type::Void};self.nl();let body=self.block_until(&[TokenKind::End])?;self.need(&TokenKind::End,"expected END TO")?;self.eat(&TokenKind::To);Ok(Function{name,params,ret,body,span:start})}
 fn extern_function(&mut self)->Result<ExternFunction,CompileError>{let start=self.need(&TokenKind::Extern,"expected EXTERN")?.span;let library=match self.bump().kind{TokenKind::Str(s)=>s,_=>return Err(CompileError::new(self.cur().span,"EXTERN expects a quoted library name"))};self.need(&TokenKind::Function,"EXTERN expects FUNCTION")?;let(name,_)=self.ident("EXTERN expects a function name")?;self.need(&TokenKind::LParen,"EXTERN functions require parameter parentheses")?;let mut params=Vec::new();if !self.at(&TokenKind::RParen){loop{let(p,_)=self.ident("expected parameter name")?;self.need(&TokenKind::As,"external parameters require AS type")?;let ty=self.type_name()?;params.push((p,ty));if !self.eat(&TokenKind::Comma){break}}}self.need(&TokenKind::RParen,"expected ) after external parameters")?;self.need(&TokenKind::Gives,"EXTERN functions require GIVES type")?;let ret=self.type_name()?;Ok(ExternFunction{library,name,params,ret,span:start})}
 fn class(&mut self)->Result<Class,CompileError>{let start=self.need(&TokenKind::Class,"expected CLASS")?.span;let(name,_)=self.ident("expected class name")?;let parent=if self.eat(&TokenKind::Extends){Some(self.ident("expected parent class")?.0)}else{None};self.nl();let mut fields=Vec::new();let mut defaults=Vec::new();let mut methods=Vec::new();while !self.at(&TokenKind::End)&&!self.at(&TokenKind::Eof){if self.at(&TokenKind::Let){let t=self.bump();let(f,_)=self.ident("expected field name")?;self.need(&TokenKind::As,"class fields require AS type")?;let ty=self.type_name()?;let init=if self.eat(&TokenKind::Eq){Some(self.expr(0)?)}else{None};fields.push((f,ty));defaults.push(init);self.nl();let _=t;}else if self.at(&TokenKind::To){methods.push(self.function()?);self.nl();}else{return Err(CompileError::new(self.cur().span,"class bodies may contain only fields and methods"))}}self.need(&TokenKind::End,"expected END CLASS")?;self.eat(&TokenKind::Class);Ok(Class{name,parent,fields,defaults,methods,span:start})}
 fn block_until(&mut self,ends:&[TokenKind])->Result<Vec<Stmt>,CompileError>{let mut b=Vec::new();self.nl();while !ends.iter().any(|x|self.at(x))&&!self.at(&TokenKind::Eof){b.push(self.stmt()?);self.nl();}Ok(b)}
 fn stmt(&mut self)->Result<Stmt,CompileError>{let t=self.cur().clone();match &t.kind{
  TokenKind::Let=>self.let_stmt(),TokenKind::Set=>self.set_stmt(),TokenKind::Say=>{self.bump();let e=self.expr(0)?;Ok(Stmt::Say(e,t.span))},
  TokenKind::Ask=>self.ask_stmt(),TokenKind::If=>self.if_stmt(),TokenKind::Repeat=>self.repeat_stmt(),TokenKind::Give=>{self.bump();self.need(&TokenKind::Back,"expected BACK after GIVE")?;let e=if self.at(&TokenKind::Newline){None}else{Some(self.expr(0)?)};Ok(Stmt::Return(e,t.span))},
  TokenKind::Break=>{self.bump();Ok(Stmt::Break(t.span))},TokenKind::Continue=>{self.bump();Ok(Stmt::Continue(t.span))},TokenKind::Try=>self.try_stmt(),TokenKind::Fail=>{self.bump();Ok(Stmt::Fail(self.expr(0)?,t.span))},
  _=>Ok(Stmt::Expr(self.expr(0)?)),}}
 fn let_stmt(&mut self)->Result<Stmt,CompileError>{let sp=self.bump().span;let mut names=Vec::new();loop{let(n,_)=self.ident("LET expects a variable name")?;let ty=if self.eat(&TokenKind::As){Some(self.type_name()?)}else{None};names.push((n,ty));if !self.eat(&TokenKind::Comma){break}}self.need(&TokenKind::Eq,"LET expects =")?;let mut vals=Vec::new();loop{vals.push(self.expr(0)?);if !self.eat(&TokenKind::Comma){break}}Ok(Stmt::Let(names,vals,sp))}
 fn set_stmt(&mut self)->Result<Stmt,CompileError>{let sp=self.bump().span;let mut lhs=Vec::new();loop{lhs.push(self.prefix()?);if !self.eat(&TokenKind::Comma){break}}self.need(&TokenKind::Eq,"SET expects =")?;let mut vals=Vec::new();loop{vals.push(self.expr(0)?);if !self.eat(&TokenKind::Comma){break}}Ok(Stmt::Set(lhs,vals,sp))}
 fn ask_stmt(&mut self)->Result<Stmt,CompileError>{let sp=self.bump().span;let prompt=self.expr(0)?;let ty;if self.eat(&TokenKind::Semi){ty=Type::String}else if self.eat(&TokenKind::Colon){ty=Type::Int}else{return Err(CompileError::new(self.cur().span,"ASK expects ; variable or : variable"))};let(name,_)=self.ident("ASK expects a variable name")?;let ty=if self.eat(&TokenKind::As){self.type_name()?}else{ty};Ok(Stmt::Ask{prompt,name,ty,span:sp})}
 fn if_stmt(&mut self)->Result<Stmt,CompileError>{let sp=self.bump().span;let cond=self.expr(0)?;self.eat(&TokenKind::Then);self.nl();let mut branches=Vec::new();let body=self.block_until(&[TokenKind::Else,TokenKind::End])?;branches.push((cond,body));let mut else_body=Vec::new();while self.eat(&TokenKind::Else){if self.eat(&TokenKind::If){let c=self.expr(0)?;self.eat(&TokenKind::Then);self.nl();let b=self.block_until(&[TokenKind::Else,TokenKind::End])?;branches.push((c,b));}else{self.nl();else_body=self.block_until(&[TokenKind::End])?;break}}self.need(&TokenKind::End,"expected END IF")?;self.eat(&TokenKind::If);Ok(Stmt::If{branches,else_body,span:sp})}
 fn repeat_stmt(&mut self)->Result<Stmt,CompileError>{let sp=self.bump().span;let r=if self.eat(&TokenKind::While){let c=self.expr(0)?;self.nl();Repeat::While{cond:c,body:self.block_until(&[TokenKind::End])?}}else if self.eat(&TokenKind::For){self.need(&TokenKind::Each,"expected EACH")?;let(n,_)=self.ident("expected loop variable")?;self.need(&TokenKind::In,"expected IN")?;let it=self.expr(0)?;self.nl();Repeat::Each{name:n,iter:it,body:self.block_until(&[TokenKind::End])?}}else{let(n,_)=self.ident("expected loop variable")?;self.need(&TokenKind::From,"expected FROM")?;let a=self.expr(0)?;self.need(&TokenKind::To,"expected TO")?;let b=self.expr(0)?;self.nl();Repeat::Counted{name:n,start:a,end:b,body:self.block_until(&[TokenKind::End])?}};self.need(&TokenKind::End,"expected END REPEAT")?;self.eat(&TokenKind::Repeat);Ok(Stmt::Repeat(r,sp))}
 fn try_stmt(&mut self)->Result<Stmt,CompileError>{let sp=self.bump().span;self.nl();let body=self.block_until(&[TokenKind::Catch])?;self.need(&TokenKind::Catch,"expected CATCH")?;let(c,_)=self.ident("CATCH expects an error variable")?;self.nl();let cb=self.block_until(&[TokenKind::End])?;self.need(&TokenKind::End,"expected END TRY")?;self.eat(&TokenKind::Try);Ok(Stmt::Try{body,catch:c,catch_body:cb,span:sp})}
 fn expr(&mut self,min:u8)->Result<Expr,CompileError>{let mut left=self.prefix()?;loop{if self.at(&TokenKind::Is){if 3<min{break}let t=self.bump();let(class_name,class_span)=self.ident("IS expects a class name")?;left=Expr::Call{callee:Box::new(Expr::Var(format!("IS::{}",class_name),class_span)),args:vec![left],span:t.span};continue}let (op,prec)=match self.cur().kind{TokenKind::Or=>(Binary::Or,1),TokenKind::And=>(Binary::And,2),TokenKind::Eq=>(Binary::Eq,3),TokenKind::NotEq=>(Binary::NotEq,3),TokenKind::Lt=>(Binary::Lt,3),TokenKind::LtEq=>(Binary::Lte,3),TokenKind::Gt=>(Binary::Gt,3),TokenKind::GtEq=>(Binary::Gte,3),TokenKind::Plus=>(Binary::Add,4),TokenKind::Minus=>(Binary::Sub,4),TokenKind::Star=>(Binary::Mul,5),TokenKind::Slash=>(Binary::Div,5),TokenKind::Percent=>(Binary::Mod,5),_=>break};if prec<min{break}let sp=self.bump().span;let right=self.expr(prec+1)?;left=Expr::Binary{left:Box::new(left),op,right:Box::new(right),span:sp};}if min==0&&self.eat(&TokenKind::If){let cond=self.expr(0)?;self.need(&TokenKind::Else,"ternary expects ELSE")?;let no=self.expr(0)?;let span=left.span();left=Expr::Ternary{yes:Box::new(left),cond:Box::new(cond),no:Box::new(no),span}}Ok(left)}
 fn prefix(&mut self)->Result<Expr,CompileError>{let t=self.bump();let mut e=match t.kind{TokenKind::Int(n)=>Expr::Int(n,t.span),TokenKind::Float(n)=>Expr::Float(n,t.span),TokenKind::Str(s)=>Expr::Str(s,t.span),TokenKind::True=>Expr::Bool(true,t.span),TokenKind::False=>Expr::Bool(false,t.span),TokenKind::Ident(s)=>Expr::Var(s,t.span),TokenKind::Minus=>Expr::Unary{op:Unary::Neg,expr:Box::new(self.expr(6)?),span:t.span},TokenKind::Not=>Expr::Unary{op:Unary::Not,expr:Box::new(self.expr(3)?),span:t.span},TokenKind::LParen=>{let x=self.expr(0)?;self.need(&TokenKind::RParen,"expected )")?;x},TokenKind::LBracket=>{let mut xs=Vec::new();if !self.at(&TokenKind::RBracket){loop{xs.push(self.expr(0)?);if !self.eat(&TokenKind::Comma){break}}}self.need(&TokenKind::RBracket,"expected ]")?;Expr::List(xs,t.span)},TokenKind::LBrace=>{let mut ps=Vec::new();if !self.at(&TokenKind::RBrace){loop{let k_raw=self.expr(0)?;let k=match k_raw{Expr::Var(n,sp)=>Expr::Str(n,sp),other=>other};self.need(&TokenKind::Colon,"expected : in dictionary")?;let v=self.expr(0)?;ps.push((k,v));if !self.eat(&TokenKind::Comma){break}}}self.need(&TokenKind::RBrace,"expected }")?;Expr::Dict(ps,t.span)},TokenKind::New=>{let(n,_)=self.ident("NEW expects a class name")?;Expr::Var(format!("NEW::{}",n),t.span)},_=>return Err(CompileError::new(t.span,"expected an expression"))};loop{if self.eat(&TokenKind::LParen){let mut args=Vec::new();if !self.at(&TokenKind::RParen){loop{args.push(self.expr(0)?);if !self.eat(&TokenKind::Comma){break}}}let r=self.need(&TokenKind::RParen,"expected ) after arguments")?;e=Expr::Call{callee:Box::new(e),args,span:r.span};}else if self.eat(&TokenKind::Dot){let(n,sp)=if self.at(&TokenKind::New){let t=self.bump();("NEW".to_string(),t.span)}else{self.ident("expected member name")?};e=Expr::Member{object:Box::new(e),name:n,span:sp};}else if self.eat(&TokenKind::LBracket){let idx=self.expr(0)?;let r=self.need(&TokenKind::RBracket,"expected ]")?;e=Expr::Index{object:Box::new(e),index:Box::new(idx),span:r.span};}else{break}}Ok(e)}
}
